    function __ESBMC_assume(bool) internal pure {}
    function run(uint v, uint d) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(address(this).balance >= d);
        c.SetMinSum(v); if (__ESBMC_reverted()) return;
        uint m0 = c.MinSum(); if (__ESBMC_reverted()) return;
        uint b0 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint e0 = address(c).balance;
        c.Deposit{value: d}(); if (__ESBMC_reverted()) return;
        assert(
            c.MinSum() == m0 && m0 == v &&
            c.balances(address(this)) == b0 + d &&
            address(c).balance == e0 + d
        );
    }
    receive() external payable {}
