pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 v, uint256 d) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= d);
        try c.SetMinSum(v) {} catch { return; }
        uint256 m0;
        try c.MinSum() returns (uint256 __r) { m0 = __r; } catch { return; }
        uint256 b0;
        try c.balances(address(this)) returns (uint256 __r) { b0 = __r; } catch { return; }
        uint e0 = address(c).balance;
        try c.Deposit{value: d}() {} catch { return; }
        assertTrue(c.MinSum() == m0 && m0 == v &&
            c.balances(address(this)) == b0 + d &&
            address(c).balance == e0 + d);
    }

    function testFuzz_run(uint256 v, uint256 d) public {
        _run(v, d);
    }

    receive() external payable {}
}
